+    markFor: markFor,
+    utcHHMM: utcHHMM,
+    flipTaskListItems: flipTaskListItems,
+    markJobDone: markJobDone,
+    DEFAULT_TEMP_PATH: DEFAULT_TEMP_PATH
+};
