/**
 * Marks the run's task-list item done. opts: { repo, number, runUrl,
 * jobResult, endTs?, tempPath? }; io: { exec, writeFile, clock, log }.
 * Returns { status: 'flipped'|'no-marker', mark, flipped, endTs }.
